public func on(event: String, callback: Callback1Argument<Progress>): Unit 订阅任务的事件。 系统能力 : SystemCapability.Request.FileTransferAgent 参数： 参数名 类型 必填 说明 event String 是 订阅的事件类型。- 取值为'progress'，表示任务进度。- 取值为'completed'，表示任务完成。- 取值为'failed'，表示任务失败。- 取值为'pause'，表示任务暂停。- 取值为'resume'，表示任务恢复。- 取值为'remove'，表示任务删除。 callback Callback1Argument < Progress > 是 发生相关的事件时触发该回调方法，返回任务信息的数据结构。 错误码： 以下错误码的详细介绍请参见 上传下载错误码 。 错误码ID 错误信息 21900005 task mode error. 示例： let fileSpec = FileSpec( path: "./taskOnTest.avi", filename: "taskOnTest.avi", mimeType: "application/octet-stream"
)
let attachments = ConfigDataType.FORMITEMS([ FormItem( name: "taskOnTest", value: FormItemValueType.FILE(fileSpec) )
])
let config = Config( action: Action.UPLOAD, url: "http://127.0.0.1", title: "taskOnTest", mode: Mode.FOREGROUND, description: "Sample code for event listening", overwrite: false, method: "PUT", data: attachments, saveas: "./", network: Network.CELLULAR, metered: false, roaming: true, retry: true, redirect: true, index: 0, begins: 0, ends: -1, gauge: false, precise: false, token: "it is a secret"
) class ProgressCallback <: Callback1Argument<Progress> { public init() {} public open func invoke(arg: Progress): Unit { Hilog.info(0, "request", "progress callback.") }
}
let createOnCallback = ProgressCallback()
try { let task = create(getContext(), config) task.on("progress", createOnCallback)
} catch (e: BusinessException) { Hilog.error(0, "TaskCreate", e.toString())
} 说明： 示例中context的获取方式请参见 getStageContext 。

