public static func addWatcher(watcher: Watcher): Option<AppEventPackageHolder> 添加应用事件观察者方法，可用于订阅应用事件。 系统能力： SystemCapability.HiviewDFX.HiAppEvent 参数： 参数名 类型 必填 说明 watcher Watcher 是 应用事件观察者。 返回值： 类型 说明 Option< AppEventPackageHolder > 订阅数据持有者，订阅失败时返回None。 错误码： 以下错误码的详细介绍请参见 应用事件打点错误码 。 错误码ID 错误信息 11102001 Invalid watcher name. 11102002 Invalid filtering event domain. 11102003 Invalid row value. 11102004 Invalid size value. 11102005 Invalid timeout value. 示例： internal import ohos.hiappevent.*
internal import ohos.hilog.* // 1. 如果观察者传入了回调的相关参数，则可以选择在自动触发的回调函数中对订阅事件进行处理
var condition = TriggerCondition(row: 1)
var appEventFilter = [AppEventFilter("button")] var watcher = Watcher("watcher1", triggerCondition: condition, onTrigger: Some({ row, size, holder => Hilog.info(0, "HiAppEnvent", "HiAppEvent onTrigger: curRow=${row}, curSize=${size}") while (let Some(v) <- holder.takeNext()) { let eventPkg = v Hilog.info(0, "HiAppEnvent", "HiAppEvent packageId=${eventPkg.packageId}") Hilog.info(0, "HiAppEnvent", "HiAppEvent row=${eventPkg.row}") Hilog.info(0, "HiAppEnvent", "HiAppEvent size=${eventPkg.size}") for (i in 0..eventPkg.data.size) { Hilog.info(0, "HiAppEnvent", "HiAppEvent info=${eventPkg.data[i]}") } } }))
HiAppEvent.addWatcher(watcher) // 2. 如果观察者未传入回调的相关参数，则可以选择使用返回的holder对象手动去处理订阅事件
let watcher = Watcher("watcher2")
let holder = HiAppEvent.addWatcher(watcher)
if (let Some(v1) <- holder) { while (let Some(v2) <- v1.takeNext()) { let eventPkg = v2 Hilog.info(0, "test_hiAppEvent_addWatcher", "HiAppEvent packageId=${eventPkg.packageId}") Hilog.info(0, "test_hiAppEvent_addWatcher", "HiAppEvent row=${eventPkg.row}") Hilog.info(0, "test_hiAppEvent_addWatcher", "HiAppEvent size=${eventPkg.size}") for (i in 0..eventPkg.data.size) { Hilog.info(0, "test_hiAppEvent_addWatcher", "HiAppEvent info=${eventPkg.data[i]}") } }
} // 3. 观察者可以在实时回调函数onReceive中处理订阅事件
var condition = TriggerCondition(row: 1, size:100)
let watcher= Watcher("watcher", triggerCondition: condition, onTrigger: {row, size, holder => Hilog.info(0, "HiAppEnvent", "HiAppEvent onTrigger: curRow=${row}, curSize=${size}")}, onReceive: {domain, AppEventGroups => Hilog.info(0, "HiAppEnvent", "domain =${domain}") let groupSize = AppEventGroups.size for (i in 0..groupSize) { Hilog.info(0, "HiAppEnvent", "name =${AppEventGroups[i].name}") let appInfosize = AppEventGroups[i].appEventInfos.size for (j in 0..appInfosize) { Hilog.info(0, "HiAppEnvent", "appEventInfo name=${AppEventGroups[i].appEventInfos[j].name}") Hilog.info(0, "HiAppEnvent", "appEventInfo domain=${AppEventGroups[i].appEventInfos[j].domain}") Hilog.info(0, "HiAppEnvent", "appEventInfo event=${AppEventGroups[i].appEventInfos[j].event.value}") let paSize = AppEventGroups[i].appEventInfos[j].params.size for (k in 0..paSize) { Hilog.info(0, "HiAppEnvent", "key=${AppEventGroups[i].appEventInfos[j].params[k].key}") let value = AppEventGroups[i].appEventInfos[j].params[k].value.value Hilog.info(0, "HiAppEnvent", "value=${value}") } } } })
HiAppEvent.addWatcher(watcher)

