public func runJavaScript(script: String, callback : AsyncCallback<String>): Unit 异步执行JavaScript脚本，并通过回调方式返回脚本执行的结果。runJavaScript需要在loadUrl完成后，比如onPageEnd中调用。 系统能力： SystemCapability.Web.Webview.Core 参数： 参数名 类型 必填 说明 script String 是 JavaScript脚本。 callback AsyncCallback<String> 是 回调执行JavaScript脚本结果。JavaScript脚本若执行失败或无返回值时，返回null。 错误码： 以下错误码的详细介绍请参见 webview错误码 。 错误码ID 错误信息 17100001 Init error. The WebviewController must be associated with a Web component. 示例： package ohos_app_cangjie_entry
import ohos.base.*
import ohos.component.*
import ohos.state_manage.*
import ohos.state_macro_manage.*
import ohos.webview.* let callback: AsyncCallback<String> = { errorCode: Option<AsyncError>, data: Option<String> => match (errorCode) { case Some(e) => AppLog.error("callback error: errcode is ${e.code}") case _ => match (data) { case Some(value) => AppLog.info("callback: get data successfully and data is ${value}") case _ => AppLog.error("callback: data is null") } }
} @Entry
@Component
class EntryView { let webController = WebviewController() func test() { Column(10) { Button("runJavaScript") .onClick { evt => AppLog.info("runJavaScript") webController.runJavaScript("test()", callback) }.width(400.px).height(150.px) Web(src: @rawfile("index.html"), controller: webController) .onPageBegin({evt => AppLog.info("page begin url: ${evt.url}") }) .onPageEnd({evt => AppLog.info("page end url: ${evt.url}") }) } }
} 加载的html文件。 <!-- index.html -->
