public func on(callback: EventCallBack1<A>): Unit 功能 ：订阅参数个数为1的指定事件。 参数 ： 参数名 类型 必填 说明 callback EventCallBack1 是 事件回调，事件触发后调用。 示例： import ohos.eventhub.* class f2 <: EventCallBack1<Int64> { public override func invoke(a: Int64) { println("f2 is invoked") }
} class f3 <: EventCallBack1<Int64> { public override func invoke(a: Int64) { println("f3 is invoked") }
} main(){ let eventhub = Eventhub let foo2: EventCallBack1<Int64> = f2() let foo3: EventCallBack1<Int64> = f3() eventhub.obtainEvent1<Int64>("click1").on(foo2) eventhub.obtainEvent1<Int64>("click1").on(foo3)
}

