) .width(400.px) .height(150.px) .margin(20.px) .fontColor(Color.BLACK) .onFocus({=> fiveButtonColor = 0xFF0000 }) .onBlur({=> fiveButtonColor = 0x1E90FF }) .groupDefaultFocus(true) .id(this.idList[4]) .key(this.idList[4]) }.tabIndex(4).focusable(true).borderWidth(1.5).borderColor(rowBoxColor).borderStyle(BorderStyle.Solid) .onFocus({=> rowBoxColor = 0x000000 }) .onBlur({=> rowBoxColor = 0xFFFFFF }) Row() { // 点击让D组件获焦 Button("RequestFocus-D") .width(400.px) .height(150.px) .margin(20.px) .fontColor(Color.BLACK) .focusable(true) .onClick { let selectId = this.idList[3] let result = FocusControl.requestFocus(selectId) if (result) { AppLog.info("Request success") } else { AppLog.info("Request failed") } } } }.width(100.percent).margin(top: 20) }
