import encoding.json.*
import std.convert.*
import std.collection.* class Utils { static var rect_left: Float64 = 0.00f64 static var rect_top: Float64 = 0.00f64 static var rect_right: Float64 = 0.00f64 static var rect_bottom: Float64 = 0.00f64 static var rect_value: HashMap<String, Float64> = HashMap<String, Float64>() //获取组件所占矩形区域坐标 static func getComponentRect(key: String): HashMap<String, Float64> { let strJson = getInspectorByKey(key) let obj = JsonValue.fromStr(strJson).asObject() let fields = obj.getFields() let children = fields.get("$rect").getOrThrow().toString() let strArr = children.split(",") rect_left = Float64.parse(strArr[0][2..]) var temp = strArr[1] rect_top = Float64.parse(temp[..temp.size - 1]) temp = strArr[2] rect_right = Float64.parse(temp[1..]) temp = strArr[3] rect_bottom = Float64.parse(temp[0..temp.size - 2]) rect_value.put("rect_left", rect_left) rect_value.put("rect_top", rect_top) rect_value.put("rect_right", rect_right) rect_value.put("rect_bottom", rect_bottom) return Utils.rect_value }
