class EntryView { @State var currentIndex: UInt32 = 0 @State var firstState: ItemState = ItemState.Normal @State var secondState: ItemState = ItemState.Normal @State var thirdState: ItemState = ItemState.Normal func build() { Column() { Stepper(currentIndex) { // 第一个步骤页 StepperItem() { Column() { Text("Page One").fontSize(35).fontColor(0x182431) Button("change status: ${this.firstState.getValue()}") .backgroundColor(0x007dFF) .onClick({ evt => if(this.firstState.toString() == "Skip") { this.firstState = ItemState.Normal } else { this.firstState = ItemState.Skip } }) } } .nextLabel("下一页") .status(this.firstState) // 第二个步骤页 StepperItem() { Column() { Text("Page Two").fontSize(35).fontColor(0x182431) Button("change status: ${this.secondState.getValue()}") .backgroundColor(0x007dFF) .onClick({ evt => if(this.secondState.toString() == "Disabled") { this.secondState = ItemState.Normal } else { this.secondState = ItemState.Disabled } }) } } .nextLabel("下一页") .prevLabel("上一页") .status(this.secondState) // 第三个步骤页 StepperItem() { Column() { Text("Page Three").fontSize(35).fontColor(0x182431) Button("change status: ${this.thirdState.getValue()}") .backgroundColor(0x007dFF) .onClick({ evt => if(this.thirdState.toString() == "Waiting") { this.thirdState = ItemState.Normal } else { this.thirdState = ItemState.Waiting } }) } } .nextLabel("下一页") .prevLabel("上一页") .status(this.thirdState) // 第四个步骤页 StepperItem() { Column() { Text("Page Four").fontSize(35).fontColor(0x182431) } } } .backgroundColor(0xF1F3F5) .onFinish({=> // 此处可处理点击最后一页的Finish时的逻辑，例如路由跳转等 AppLog.info("onFinish") }) .onSkip({=> // 此处可处理点击跳过时的逻辑，例如动态修改Stepper的index值使其跳转到某一步骤页等 AppLog.info("onSkip") }) .onChange({prevIndex: UInt32, index: UInt32 => if(index != 0){ currentIndex = index } }) } .width(100.percent) .padding(top: 5) }
} stepper

