该示例用于说明GridCol常用方法、构造函数以及循环渲染的使用，并展示span、offset的效果。 package ohos_app_cangjie_entry
import ohos.base.*
import ohos.component.*
import ohos.state_manage.*
import ohos.state_macro_manage.*
import std.collection.* @Entry
@Component
class EntryView { @State var bgColors: Array<Color> = [Color.RED, Color.GREEN, Color.GRAY, Color.RED, Color.GREEN, Color.BLUE, Color.GRAY] @State var currentBp: String = "" func build() { Column { //GridRow设置中一行有5列 GridRow( columns: 5, gutter: GutterOption(x: 5.vp, y: 10.vp), breakpoints: BreakPoints( value: [400.vp, 600.vp, 800.vp], reference: BreakpointsReference.WindowSize ), direction: GridRowDirection.GridRowRow ) { //GridCol栅格子组件，必须作为栅格容器组件(GridRow)的子组件使用。 //构造第1个GridCol子组件，栅格占2列，为第1,2列。 GridCol() { Row() { Text("GridCol 1: span=2").fontColor(Color.GRAY).fontSize(12) }.width(100.percent).height(40.vp) }.borderColor(Color.BLUE).borderWidth(2.vp).span(2) //构造第2个GridCol子组件，栅格占2列，离上一个栅格的偏移列数为1列，因此该栅格占第4.5列 GridCol() { Row() { Text("GridCol 2: span=2, offset=1").fontColor(Color.GRAY).fontSize(12) }.width(100.percent).height(40.vp) }.borderColor(Color.GREEN).borderWidth(2.vp).span(2).offset(1) //构造第3个GridCol子组件，栅格占1列，距离上一个栅格偏移列数为2列，由于换行，因此该栅格占下一行的第3列 GridCol() { Row() { Text("GridCol 3: span=1, offset=2").fontColor(Color.GRAY).fontSize(12) }.width(100.percent).height(40.vp) }.borderColor(Color.RED).borderWidth(2.vp).span(1).offset(2) //循环渲染栅格子组件 ForEach(bgColors, itemGeneratorFunc: { color: Color, index: Int64 => GridCol() { Row().height(20.vp) } .borderWidth(2.vp) .borderColor(color) .span(GridColColumnOption(xs:12, sm:12, md:12, lg:12, xl:12, xxl: 12)) .id("my_GridCol") }) }.width(100.percent).height(100.percent).onBreakpointChange({ bp => currentBp = bp }).alignItems(ItemAlign.Center).id("row") }.width(80.percent).margin(left: 10, top: 5, bottom: 5).height(300).borderWidth(2) }
} grid_col

