package ohos_app_cangjie_entry
import ohos.base.*
import ohos.component.*
import ohos.state_manage.*
import ohos.state_macro_manage.*
import std.collection.* @Entry
@Component
class EntryView { @State var bgColors: Array<Color> = [Color.RED, Color.GREEN, Color.BLUE, Color.GRAY, Color.RED, Color.GREEN, Color.BLUE, Color.GRAY] @State var currentBp: String = "" func build() { Column { GridRow( //设置栅格在不同宽度设备类型下对应的显示栅格列数。 //xs:最小宽度类型设备 sm:小宽度类型设备 md:中等宽度类型设备。 //lg:大宽度类型设备 xl:特大宽度类型设备 xxl:超大宽度类型设备。 columns: GridRowColumnOption(xs: 5, sm: 6, md: 7, lg: 8, xl: 9, xxl: 10), //设置栅格布局间距，x代表水平方向，y代表垂直方向。 gutter: GutterOption(x: 5.vp, y: 10.vp), //设置断点值的断点数列以及基于窗口或容器尺寸的相应参照。 breakpoints: BreakPoints( //启用xs,sm,md,lg四个断点 value: [200.vp, 300.vp, 400.vp], //设置断点位置的单调递增数组。 reference: BreakpointsReference.WindowSize ), //设置为以窗口为参照。 //设置栅格布局排列方向,按照行方向排列。 direction: GridRowDirection.GridRowRow ) { //循环渲染出bgColors对应颜色的栅格 ForEach( bgColors, itemGeneratorFunc: { color: Color, index: Int64 => GridCol() { Row().width(100.percent).height(20.vp) }.borderWidth(2.vp).borderColor(color).span(1) } ) } .width(100.percent) .height(200) .onBreakpointChange({bp => currentBp = bp}) .alignItems(ItemAlign.Center) //设置GridRow中的GridCol垂直主轴方向对齐方式。这里设置为居中对齐。 GridRow( //设置布局列数为5列 columns: 5, //设置栅格布局间距，水平方向为5vp，垂直方向10vp。 gutter: GutterOption(x: 5.vp, y: 10.vp), //设置断点值的断点数列以及基于窗口或容器尺寸的相应参照。 breakpoints: BreakPoints( //启用xs,sm,md,lg四个断点 value: [400.vp, 600.vp, 800.vp], //设置断点位置的单调递增数组。 reference: BreakpointsReference.WindowSize //设置为以窗口为参照。 ), direction: GridRowDirection.GridRowRow ) { ForEach( bgColors, itemGeneratorFunc: { color: Color, index: Int64 => GridCol() { Row().width(100.percent).height(20.vp) }.borderWidth(2.vp).borderColor(color).span( GridColColumnOption(xs: 1, sm: 2, md: 3, lg: 4, xl: 5, xxl: 6)) } ) } .width(100.percent) .height(100.percent) .onBreakpointChange({bp => currentBp = bp}) .alignItems(ItemAlign.Center) }.width(80.percent).margin(left: 10, top: 5, bottom: 5).height(400).borderWidth(2) }
} grid_row

