public static func getBundleInfoForSelf(bundleFlags: Int32): BundleInfo 根据给定的bundleFlags获取当前应用的BundleInfo。 系统能力： SystemCapability.BundleManager.BundleFramework.Core 参数： 参数名 类型 必填 说明 bundleFlags Int32 是 指定返回的BundleInfo所包含的信息，具体可参考 BundleFlag 。 返回值： 类型 说明 BundleInfo BundleInfo对象，返回当前应用的BundleInfo。 示例1： main() { //只获取最基础的应用包信息 let bundleFlags = GET_BUNDLE_INFO_DEFAULT.getValue() let res = BundleManager.getBundleInfoForSelf(bundleFlags) return 0
} 示例2： main() { //在最基础的应用包信息的基础上，附带上应用信息，HAP模块信息，包含HAP模块信息中的能力信息 let bundleFlags = GET_BUNDLE_INFO_DEFAULT.getValue() | GET_BUNDLE_INFO_WITH_APPLICATION.getValue() | GET_BUNDLE_INFO_WITH_HAP_MODULE.getValue() | GET_BUNDLE_INFO_WITH_ABILITY.getValue() let res = BundleManager.getBundleInfoForSelf(bundleFlags) return 0
}

