@Link 与 @State 有相同的语义，但初始化方式不同。 @Link 装饰的变量必须使用其父组件提供的变量进行初始化，被 @Link 修饰的成员变量必须指明类型，且只能使用 var 来声明。允许组件内部修改 @Link 变量，且更改会通知给父组件，即 @Link 属于双向数据绑定。 @Link 修饰当前组件所拥有的状态，仅可在子组件中定义。 支持多种类型 ： @Link 变量的值与 @State 变量的类型相同。 私有 ：仅在组件内访问；不可被 public protected 等修饰符修饰； 支持多个实例 ：一个组件中可以定义多个标有 @Link 的属性； 双向通信 ：子组件对 @Link 变量的更改将同步修改父组件的 @State 变量； 示例 package ohos_app_cangjie_entry import ohos.base.*
import ohos.component.*
import ohos.state_manage.*
import ohos.state_macro_manage.* @Component
class SubSubComponent { @Link var count: Int64 var commonCount: Int64 = 0 func build() { Column { Button("This is a case of @Link ${count} _____ SubSubComponent ${commonCount}").onClick({evt => count = count + 1 }) } }
} @Component
class SubComponent { @Link var count: Int64 func build() { Column { Button("This is a case of @Link ${count} _____ SubComponent") .onClick({evt => count = count + 1 }) SubSubComponent(count: count, commonCount: count) } }
} @Entry
@Component
class ParentComponent { @State var count: Int64 = 0 func build() { Column { Button("This is a case of @Link ${count} _____ ParentComponent") .onClick({evt => count = count + 1 }) SubComponent(count: count) } }
}

