@Builder 装饰的方法用于定义组件的声明式UI描述，在一个自定义组件内快速生成多个布局内容。 @Builder 装饰方法的功能和语法规范与render函数相同。 支持泛型参数、泛型约束、命名参数、命名参数默认值等仓颉函数基本功能； 可以修饰全局函数，也可以修饰类的成员函数； 不支持使用 open 修饰并被重写（我们建议 @Builder 函数只定义在全局或 @Component 修饰的类中）； 不支持使用 static 修饰作为类的静态方法； 函数的返回值类型为 Unit，返回值类型可以省略； 函数体中只允许包含 UI 组件声明（UI 组件声明包括：内置组件、@Component 修饰类的实例构造、@Builder 修饰函数的调用）； 可以使用导出普通仓颉函数同样的策略，导出 @Builder 修饰的函数。 示例1 package ohos_app_cangjie_entry import ohos.base.*
import ohos.component.*
import ohos.state_manage.*
import ohos.state_macro_manage.* @Builder
func f(fontSz: Int64, color: Color) { Text("hello world").fontSize(fontSz).fontColor(color)
} @Entry
@Component
class EntryView { func build() { Column(20) { f(20, Color.BLUE) } }
} 示例2 对于对象中使用 CustomBuilder 时，可以通过 bind 方法将 Builder 函数 ListItemGroup 中使用的 builder。 package ohos_app_cangjie_entry
import ohos.base.*
import ohos.component.*
import ohos.state_manage.*
import ohos.state_macro_manage.* struct TimeTable { let title: String let projects: Array<String> public init(title:String,projects: Array<String>){ this.title = title this.projects = projects }
} @Entry
@Component
class EntryView { let timeTable: Array<TimeTable> = [ TimeTable("星期一",["语文", "数学", "英语"]), TimeTable("星期二",["物理", "化学", "生物"]), TimeTable("星期三",["历史", "地理", "政治"]), TimeTable("星期四",["美术", "音乐", "体育"])] @Builder func itemHead(text:String) { Text(text) .fontSize(20) .backgroundColor(0xAABBCC) .width(100.percent) .padding(10) } @Builder func itemFoot(num:Int64) { Text("共" + "${num}" + "节课") .fontSize(16) .backgroundColor(0xAABBCC) .width(100.percent) .padding(5) } func build() { Column() { List(space: 20) { ForEach(this.timeTable, itemGeneratorFunc: {item:TimeTable ,_:Int64 => ListItemGroup(ListItemGroupParams(header:{=>bind(this.itemHead,this)(item.title)},footer:{=>bind(this.itemFoot,this)(item.projects.size)})){ ForEach(item.projects,itemGeneratorFunc: {project:String,_:Int64=> ListItem(){ Text(project) .width(100.percent) .height(100) .fontSize(20) .textAlign(TextAlign.Center) .backgroundColor(0xFFFFFF) }}) } }) } } .height(800.vp) .backgroundColor(Color(0XD3D3D3)) }
