@BuilderParam 用来装饰指向@Builder方法的变量，开发者可在初始化自定义组件时对此属性进行赋值，为自定义组件增加特定的功能。 所修饰变量的类型为函数类型，且返回值类型为 Unit； 所修饰的变量声明中，变量的类型需要显示标注； 只能修饰类的成员变量声明，禁止修饰全局变量（否则将产生编译错误）； 所修饰的类成员变量遵循 private 修饰符的可见性（即：只允许在类内部使用）； 所修饰变量可以是可变的，也可以是不可变的，变量的可变性遵循仓颉语法由 let/var 关键字标识。 示例 package ohos_app_cangjie_entry import ohos.base.*
import ohos.component.*
import ohos.state_manage.*
import ohos.state_macro_manage.* @Entry
@Component
class EntryView { @Builder func f1(): Unit { f<Int64>(100, 30, color: Color.BLACK) } @Builder func f2(): Unit { f<String>("hello", 30, color: Color.RED) } func build() { Column(10) { FrameView(ab: f1, color: Color.GREEN) FrameView(ab: f2, color: Color.GRAY) } }
} @Component
class FrameView { @BuilderParam let ab: () -> Unit let color: Color func build() { Column(10) { ab() }.backgroundColor(color) }
} @Builder
func f<T>(label: T, fontSz: Int64, color!: Color = Color.WHITE): Unit where T <: ToString { Text("${label}").fontSize(fontSz).fontColor(color)
}

