// 定义共享类
class Data <: SharedObject { Data( // 定义2个属性 var id: Int64, let name: String ) {} static init() { // 注册导出到ark的函数 JSModule.registerFunc("createData", createData) } // 创建共享对象 static func createData(context: JSContext, _: JSCallInfo): JSValue { let data = Data(1, "abc") let jsExternal = context.external(data) // 创建空JSObject let object = context.object() // 把js对仓颉对象的引用挂在JSObject的隐藏属性上 object.attachCJObject(jsExternal) // 为js对象增加2个方法 object["setId"] = context.function(setDataId).toJSValue() object["getId"] = context.function(getDataId).toJSValue() return object.toJSValue() } // 设置对象的id static func setDataId(context: JSContext, callInfo: JSCallInfo): JSValue { // 获取this指针 let thisArg = callInfo.thisArg let arg0 = callInfo[0] // 把this指针转换为JSObject let thisObject = thisArg.asObject(context) // 从JSObject上获取隐藏属性 let jsExternal = thisObject.getAttachInfo().getOrThrow() // 从js对仓颉对象的引用上获取仓颉对象 let data = jsExternal.cast<Data>().getOrThrow() // 把参数0转换为Float64 let value = arg0.toNumber() // 修改仓颉对象的属性 data.id = Int64(value) let result = context.undefined().toJSValue() return result } // 获取对象的id static func getDataId(context: JSContext, callInfo: JSCallInfo): JSValue { let thisArg = callInfo.thisArg let thisObject = thisArg.asObject(context) let jsExternal = thisObject.getAttachInfo().getOrThrow() let data = jsExternal.cast<Data>().getOrThrow() let result = context.number(Float64(data.id)).toJSValue() return result }
}

