func addBigInts(context: JSContext, callInfo: JSCallInfo): JSValue { // 把JSValue转换为JSBigInt let a: JSBigInt = callInfo[0].asBigInt(context) // 从JSBigInt读取BigInt let bigintValue = a.toBigInt() // 把JSValue转换为BigInt let b: BigInt = callInfo[1].toBigInt(context) // 对2个BigInt相加 let c = bigintValue + b // 把BigInt转换为JSValue并返回 return context.bigint(c).toJSValue()
}

