// 仓颉互操作函数：创建对象，该对象有一个只读属性
func createObject(context: JSContext, callInfo: JSCallInfo): JSValue { // 创建symbol let symbol = context.symbol(description: "hidden property") // 创建对象 let object = context.object() // 以symbol做键给属性赋值 object[symbol] = context.number(1.0).toJSValue() // 为对象定义accessor object.defineOwnAccessor(context.string("id"), getter: context.function { context, callInfo => // 获取this对象 let self = callInfo.thisArg.asObject(context) // 以symbol做键访问对象属性 let id = self[symbol] return id }) return object.toJSValue()
}

